 private final Runnable networkTick=new Runnable(){public void run(){if(!resumed)return;long tickNow=SystemClock.elapsedRealtime();if(game==null||Math.hypot(game.dx,game.dy)<=.1)lastMovementSent=0;if(playing&&!requestInFlight&&SystemClock.elapsedRealtime()>=nextNetworkAt){nextNetworkAt=SystemClock.elapsedRealtime()+100;if(needsRejoin){request("POST","/join",new JSONObject(),false);}else if(attackRequested){attackRequested=false;attack();}else if(pendingAction!=null){JSONObject queued=pendingAction;pendingAction=null;sendAction(queued);}else if(game!=null&&Math.hypot(game.dx,game.dy)>.1){try{double wx=game.dx/2+game.dy,wy=game.dy-game.dx/2,worldLength=Math.hypot(wx,wy),stickLength=Math.min(1,Math.hypot(game.dx,game.dy));double movementDt=lastMovementSent==0?.1:Math.min(.25,(tickNow-lastMovementSent)/1000.0);lastMovementSent=tickNow;JSONObject cmd=new JSONObject().put("type","move").put("dx",wx/worldLength*stickLength).put("dy",wy/worldLength*stickLength).put("sprint",game.sprint.active()).put("blocking",game.blockHeld).put("dt",movementDt);sendAction(cmd);}catch(Exception ignored){}}else if(game!=null&&game.blockHeld){action("block","enabled",true);}else request("GET","/state",null,false);}ui.postDelayed(this,20);}};
