 private final HashSet<String> exploredMapCells=new HashSet<>();private String exploredMapOwner="";private final Path exploredMapPath=new Path();private boolean exploredMapDirty=true;private int exploredMapCellSize=75;
 private void rememberMap(JSONObject next){JSONObject player=next.optJSONObject("you"),view=next.optJSONObject("visibility");if(player==null||view==null)return;String owner=player.optString("id")+":"+player.optString("characterId");if(!owner.equals(exploredMapOwner)||next.has("mapExplored")){exploredMapCells.clear();exploredMapOwner=owner;exploredMapDirty=true;}exploredMapCellSize=view.optInt("cellSize",75);for(JSONArray cells:new JSONArray[]{next.optJSONArray("mapExplored"),view.optJSONArray("explored")})if(cells!=null)for(int i=0;i<cells.length();i++)if(exploredMapCells.add(cells.optString(i)))exploredMapDirty=true;}
 private void maskUnexploredMap(Canvas canvas,Paint brush,float width,float height){if(exploredMapDirty){exploredMapPath.reset();for(String cell:exploredMapCells){int comma=cell.indexOf(',');if(comma<1)continue;try{float x=Integer.parseInt(cell.substring(0,comma))*exploredMapCellSize,y=Integer.parseInt(cell.substring(comma+1))*exploredMapCellSize;exploredMapPath.addRect(x,y,x+exploredMapCellSize,y+exploredMapCellSize,Path.Direction.CW);}catch(NumberFormatException ignored){}}exploredMapDirty=false;}canvas.save();canvas.clipPath(exploredMapPath,Region.Op.DIFFERENCE);brush.setColor(Color.BLACK);canvas.drawRect(0,0,width,height,brush);canvas.restore();}
