 private boolean inSafeTown(){if(state!=null&&state.has("protected"))return state.optBoolean("protected");JSONArray towns=state==null?null:state.optJSONArray("towns");if(towns==null)return true;JSONObject p=me();for(int i=0;i<towns.length();i++){JSONObject t=towns.optJSONObject(i);if(t!=null&&Math.hypot(t.optDouble("x")-p.optDouble("x"),t.optDouble("y")-p.optDouble("y"))<=t.optDouble("radius"))return true;}return false;}
