 private String equippedWeapon(){JSONObject bag=me().optJSONObject("inventory");String chosen=me().optString("equippedWeapon");if("unarmed".equals(chosen))return "";if(bag!=null&&!chosen.isEmpty()&&bag.optInt(chosen)>0)return chosen;if(bag!=null)for(String item:new String[]{"crossbow","longbow","sword","spear","axe","bow"})if(bag.optInt(item)>0)return item;return "";}
