 private boolean targetAllowed(JSONObject target,double range){if(target==null||target.optBoolean("yours")||target.optDouble("hp")<=0||inSafeTown()||me().optDouble("hp")<=0)return false;if(Math.hypot(target.optDouble("x")-me().optDouble("x"),target.optDouble("y")-me().optDouble("y"))>range+.001)return false;JSONArray towns=state.optJSONArray("towns");if(towns!=null)for(int i=0;i<towns.length();i++){JSONObject town=towns.optJSONObject(i);if(Math.hypot(target.optDouble("x")-town.optDouble("x"),target.optDouble("y")-town.optDouble("y"))<=town.optDouble("radius"))return false;}return true;}
 private boolean visibleStrike(JSONObject target){double x=me().optDouble("x"),y=me().optDouble("y"),dx=target.optDouble("x")-x,dy=target.optDouble("y")-y;int steps=(int)Math.ceil(Math.hypot(dx,dy)/8);JSONObject room=state.optJSONObject("room");JSONArray objects=room==null?state.optJSONArray("village"):room.optJSONArray("fixtures");for(int i=1;i<steps;i++){double tx=x+dx*i/steps,ty=y+dy*i/steps;if(room!=null&&(tx<25||ty<35||tx>room.optDouble("width")-25||ty>room.optDouble("height")-25))return false;if(objects!=null)for(int j=0;j<objects.length();j++){JSONObject b=objects.optJSONObject(j);if(room==null){if(Math.abs(tx-b.optDouble("x"))<b.optDouble("halfWidth")+10&&ty>b.optDouble("y")-b.optDouble("depth")-10&&ty<b.optDouble("y")+10)return false;}else if(tx>b.optDouble("x")-12&&tx<b.optDouble("x")+b.optDouble("w")+12&&ty>b.optDouble("y")-12&&ty<b.optDouble("y")+b.optDouble("h")+12)return false;}}return true;}
 private JSONObject combatTarget(){String weaponId=equippedWeapon();if(targetState==state&&targetWeapon.equals(weaponId))return cachedTarget;targetState=state;targetWeapon=weaponId;cachedTarget=null;JSONObject weapon=MenuArt.get(this).items.get(weaponId);if(state==null||weapon==null||!weapon.has("damage")||inSafeTown()||me().optDouble("hp")<=0){rangedLockId="";return null;}boolean ranged=weapon.has("ammo")||weapon.has("damageType");double range=weapon.optDouble("range");ArrayList<JSONObject> list=new ArrayList<>();for(String collection:new String[]{"wildlife","enemies","players","companions","structures"}){JSONArray items=state.optJSONArray(collection);if(items!=null)for(int i=0;i<items.length();i++)list.add(items.optJSONObject(i));}boolean livingTarget=false;for(JSONObject candidate:list)if(candidate!=null&&!candidate.has("targetGroup")&&targetAllowed(candidate,range)&&visibleStrike(candidate)){livingTarget=true;break;}if(livingTarget&&(!ranged||rangedLockId.isEmpty()))list.removeIf(candidate->candidate!=null&&candidate.has("targetGroup"));String[] ids=new String[list.size()];double[] distances=new double[list.size()];boolean[] eligible=new boolean[list.size()];for(int i=0;i<list.size();i++){JSONObject target=list.get(i);ids[i]=target==null?"":target.optString("id");distances[i]=target==null?Double.MAX_VALUE:Math.hypot(target.optDouble("x")-me().optDouble("x"),target.optDouble("y")-me().optDouble("y"));eligible[i]=targetAllowed(target,range)&&visibleStrike(target);}int chosen=TargetLock.choose(ranged?rangedLockId:"",ids,distances,eligible,range);if(chosen>=0)cachedTarget=list.get(chosen);rangedLockId=ranged&&cachedTarget!=null?cachedTarget.optString("id"):"";return cachedTarget;
 }
 private JSONObject targetInRange(double limit){if(state==null||inSafeTown())return null;JSONObject best=null;double range=limit+.001;for(String collection:new String[]{"wildlife","enemies","players","companions","structures"}){JSONArray list=state.optJSONArray(collection);if(list==null)continue;for(int i=0;i<list.length();i++){JSONObject target=list.optJSONObject(i);if(target==null||target.optBoolean("yours")||target.optDouble("hp")<=0)continue;double distance=Math.hypot(target.optDouble("x")-me().optDouble("x"),target.optDouble("y")-me().optDouble("y"));boolean safe=false;JSONArray towns=state.optJSONArray("towns");if(towns!=null)for(int t=0;t<towns.length();t++){JSONObject town=towns.optJSONObject(t);if(Math.hypot(target.optDouble("x")-town.optDouble("x"),target.optDouble("y")-town.optDouble("y"))<=town.optDouble("radius"))safe=true;}if(!safe&&distance<range){range=distance;best=target;}}}return best;}
 private void useHotbar(int slot){JSONArray bar=me().optJSONArray("hotbar");String item=bar==null?"":bar.optString(slot,"");if(item.isEmpty()){inventory();feedback("Drag any backpack item onto hotbar slot "+(slot+1));return;}JSONObject bag=me().optJSONObject("inventory"),definition=MenuArt.get(this).items.get(item);if(bag==null||bag.optInt(item)<=0){feedback(MenuArt.get(this).name(item)+" — none in backpack");return;}if(definition!=null&&(definition.optBoolean("blackpowderAmmo")||definition.optBoolean("handheld")||definition.has("nutrition")||definition.has("damage")||definition.has("armour")||item.equals("shield")||item.equals("bandage")||item.equals("torch")||item.equals("waterskin")))action("use","item",item);else feedback(MenuArt.get(this).name(item)+" ×"+bag.optInt(item)+" — crafting / material item");}
 private void companionDetails(){JSONObject pet=state==null?null:state.optJSONObject("companion");if(pet==null){feedback("Choose a role on the v0.12 server to receive your companion");return;}long now=System.currentTimeMillis()+serverClockOffset;long cooldown=Math.max(0,(pet.optLong("skillReadyAt")-now+999)/1000);String mode=pet.optString("mode");String detail="Level: "+pet.optInt("level",1)+"  |  XP: "+pet.optString("xp","0")+"\nHealth: "+pet.optInt("hp")+" / "+pet.optInt("maxHp")+"  |  "+mode.toUpperCase()+"\n\n"+pet.optString("skill")+"\n"+pet.optString("skillDescription")+"\nSkill: "+(cooldown==0?"Ready":cooldown+"s cooldown")+"\n\nUse the single STAY / FOLLOW button to hold position or return to following.\n\nAfter your death, your companion waits at your safe-town respawn point. If defeated, it recovers there after 60 seconds.\n\nMove and resize Stay / Follow button in Button configuration.";new AlertDialog.Builder(this).setTitle(pet.optString("name")).setMessage(detail).setPositiveButton("Close",null).show();}
 private void attack(){if(requestInFlight){attackRequested=true;return;}attackRequested=false;if(me().optBoolean("mounted")){feedback("Dismount to fight or harvest");return;}if(game!=null&&game.blockHeld){feedback("Release block before attacking");return;}if(inSafeTown()){if(!harvestNearest())feedback("SAFE TOWN — combat is disabled");return;}String weapon=equippedWeapon();JSONObject definition=MenuArt.get(this).items.get(weapon);if(definition==null){feedback("Equip a weapon or hand tool first");return;}if(!definition.has("damage")){if(!harvestNearest())feedback("Use INTERACT with this tool near its resource");return;}long now=SystemClock.elapsedRealtime();if(now-localSwingAt<definition.optInt("reloadMs",800)||System.currentTimeMillis()+serverClockOffset<me().optLong("nextAttackAt")){feedback("Weapon reloading");return;}if(me().optDouble("stamina")<10){feedback("Not enough stamina");return;}JSONObject target=combatTarget();if(target==null&&harvestNearest())return;String ammo=definition.optBoolean("blackpowder")?me().optString("selectedAmmo","roundBall"):definition.optString("ammo","");if(!ammo.isEmpty()&&!ammo.equals("null")&&me().optJSONObject("inventory").optInt(ammo)<=0){feedback("No "+ammo+" available");return;}if(target==null&&!ammo.isEmpty()&&!ammo.equals("null")){feedback("No clear target in weapon range");return;}localSwingAt=now;localSwingWeapon=weapon;localAimDX=target!=null?(float)(target.optDouble("x")-me().optDouble("x")):game.lastDX/2+game.lastDY;localAimDY=target!=null?(float)(target.optDouble("y")-me().optDouble("y")):game.lastDY-game.lastDX/2;if(game!=null)game.invalidate();if(target==null){feedback("Weapon swung — no target in reach");return;}try{sendAction(new JSONObject().put("type","attack").put("target",target.optString("id")).put("weapon",weapon));}catch(Exception ignored){}}

