 private JSONObject creationRole(String id){try{JSONArray roles=state==null?null:state.optJSONArray("roles");JSONObject out=new JSONObject();if(roles!=null)for(int i=0;i<roles.length();i++){JSONObject role=roles.optJSONObject(i);if(role!=null&&id.equals(role.optString("id"))){out=new JSONObject(role.toString());break;}}if(modernWorld()&&id.equals("hunter")){JSONObject kit=out.optJSONObject("items");if(kit!=null)kit.remove("fishingRod");out.put("description","A hunting bow and arrows for ranged combat.");}if(me()!=null&&me().optBoolean("legacyCharacter")&&state.optJSONObject("companion")!=null)out.put("companion",state.optJSONObject("companion"));return out;}catch(JSONException e){return new JSONObject();}}
 private void characterCreationScreen(){stopControls();playView=null;roleView=null;pendingAction=null;characterCreation=new SurvivorCreationView(this,new SurvivorCreationView.Host(){public boolean additionalCharacter(){return !me().optBoolean("creationRequired")&&ClassSprites.supported(me().optString("role"));}public boolean existingSurvivor(){return !me().optBoolean("creationRequired");}public void create(String name,String appearance,String faction,String profession,String companion){try{if(!me().optBoolean("creationRequired")&&ClassSprites.supported(me().optString("role"))){JSONObject all=state.optJSONObject("services"),master=all==null?null:all.optJSONObject("characters");JSONArray rows=master==null?null:master.optJSONArray("rows");if(rows!=null)for(int i=0;i<rows.length();i++){JSONObject row=rows.optJSONObject(i);if(row!=null&&profession.equals(row.optString("characterUnlock"))&&row.optJSONObject("action")!=null){JSONObject command=new JSONObject(row.optJSONObject("action").toString()).put("name",name).put("appearance",appearance).put("companion",companion);sendAction(command);return;}}feedback("Unlock this class at your town Character Master when pricing is available.");return;}sendAction(new JSONObject().put("type",me().optBoolean("creationRequired")?"createCharacter":"adoptReferenceClass").put("name",name).put("appearance",appearance).put("faction",faction).put("profession",profession).put("companion",companion));}catch(JSONException e){feedback("Could not create character");}}public String status(){return !me().optBoolean("creationRequired")&&ClassSprites.supported(me().optString("role"))?"Additional characters unlock at the town Character Master.":status;}public void back(){characterCreation=null;if(playing)openPlayPreview();else showMenu();}public String legacyProfession(){return me().optBoolean("creationRequired")&&me().optBoolean("legacyCharacter")?me().optString("role",""):"";}public JSONObject definition(String id){return creationRole(id);}public JSONObject previewCharacter(){return me().optBoolean("creationRequired")&&me().optBoolean("legacyCharacter")?me():null;}public String spawnTown(String faction){JSONArray towns=state.optJSONArray("towns");int index=faction.equals("bandit")?1:0;JSONObject town=towns==null?null:towns.optJSONObject(index);return town==null?(index==0?"Trader Town A":"Trader Town B"):town.optString("name");}});setContentView(characterCreation);}
