 private interface GridChoice {void choose(int index);}
 private void gridChoices(String title,String[] names,int page,GridChoice choose){LinearLayout grid=new LinearLayout(this);grid.setOrientation(1);grid.setPadding(10,4,10,4);final AlertDialog dialog=new AlertDialog.Builder(this).setTitle(title+"  "+(page+1)+"/"+((names.length+5)/6)).setView(grid).create();for(int row=0;row<3;row++){LinearLayout line=new LinearLayout(this);for(int col=0;col<2;col++){final int index=page*6+row*2+col;Button b=new Button(this);b.setText(index<names.length?names[index]:"");b.setTextSize(12);b.setAllCaps(false);b.setEnabled(index<names.length);line.addView(b,new LinearLayout.LayoutParams(0,(int)(44*getResources().getDisplayMetrics().density),1));b.setOnClickListener(v->{dialog.dismiss();choose.choose(index);});}grid.addView(line);}LinearLayout nav=new LinearLayout(this);for(int i=0;i<3;i++){final int n=i;Button b=new Button(this);b.setText(new String[]{"Previous","Close","Next"}[i]);b.setTextSize(12);b.setEnabled(i==1||i==0&&page>0||i==2&&(page+1)*6<names.length);nav.addView(b,new LinearLayout.LayoutParams(0,(int)(44*getResources().getDisplayMetrics().density),1));b.setOnClickListener(v->{dialog.dismiss();if(n!=1)gridChoices(title,names,page+(n==0?-1:1),choose);});}grid.addView(nav);dialog.show();}
 private JSONObject harvestTarget(boolean usableOnly){return harvestTarget(usableOnly,true);}
 private JSONObject harvestTarget(boolean usableOnly,boolean allowHand){if(state==null)return null;String tool=equippedWeapon();JSONArray resources=state.optJSONArray("resources");JSONObject best=null;double closest=120.001;int priority=3;long now=System.currentTimeMillis()+serverClockOffset;if(resources!=null)for(int i=0;i<resources.length();i++){JSONObject node=resources.optJSONObject(i);if(node.optInt("remaining")<=0&&node.optLong("readyAt")>now)continue;String required=node.optString("requiredTool","");boolean hand=required.isEmpty()||required.equals("null");if(hand&&!allowHand)continue;if(usableOnly&&!hand&&!tool.equals(required))continue;double d=Math.hypot(node.optDouble("x")-me().optDouble("x"),node.optDouble("y")-me().optDouble("y"));int rank=usableOnly&&hand?1:0;if(d<=120&&(rank<priority||rank==priority&&d<closest)){priority=rank;closest=d;best=node;}}return best;}
 private boolean harvestNearest(){return harvestNearest(false,false);}
 private boolean harvestNearest(boolean explain){return harvestNearest(explain,true);}
 private boolean harvestNearest(boolean explain,boolean allowHand){if(me().optBoolean("mounted")){if(explain)feedback("Dismount before harvesting");return false;}JSONObject target=harvestTarget(true,allowHand);if(target==null){if(explain){JSONObject nearby=harvestTarget(false);feedback(nearby==null?"Move closer to the resource's trunk or base":"Equip "+MenuArt.get(this).name(nearby.optString("requiredTool"))+" in Hands first");}return false;}if(System.currentTimeMillis()+serverClockOffset-me().optLong("lastGather")<700)return true;try{sendAction(new JSONObject().put("type","gather").put("target",target.optString("id")).put("toolOnly",!allowHand));}catch(JSONException ignored){}return true;}

