  private void drawWorldVisibility(Canvas c,float px,float py,float left,float top,float right,float bottom,boolean indoors){
   if(indoors)return;
   JSONObject view=state.optJSONObject("visibility");
   if(view==null)return;
   float radius=(float)view.optDouble("radius",500),size=(float)view.optDouble("cellSize",75);
   Path explored=fogPath;JSONArray cells=view.optJSONArray("explored");
   if(view!=fogVisibility){fogVisibility=view;explored.reset();
   if(cells!=null)for(int i=0;i<cells.length();i++){String[] xy=cells.optString(i).split(",");if(xy.length!=2)continue;try{float x=Integer.parseInt(xy[0])*size,y=Integer.parseInt(xy[1])*size;explored.addRect(x,y,x+size,y+size,Path.Direction.CW);}catch(NumberFormatException ignored){}}
   explored.addCircle(px,py,radius,Path.Direction.CW);}
   c.save();c.clipPath(explored,Region.Op.DIFFERENCE);paint.setColor(Color.BLACK);c.drawRect(left,top,right,bottom,paint);c.restore();
  }
