  private boolean shieldEquipped(){JSONObject bag=me().optJSONObject("inventory");return me().optBoolean("equippedShield")&&bag!=null&&bag.optInt("shield")>0;}
  private void repeatAttack(){
   if(me().optInt("hp")<=0){heldAttack.cancel();return;}JSONObject weapon=MenuArt.get(MainActivity.this).items.get(equippedWeapon());if(weapon==null||!weapon.has("damage"))return;
   long now=SystemClock.elapsedRealtime();boolean ready=!mapOpen&&!requestInFlight&&pendingAction==null&&!blockHeld&&!inSafeTown()&&!me().optBoolean("mounted")&&me().optDouble("stamina")>=10&&now-localSwingAt>=weapon.optInt("reloadMs",800)&&System.currentTimeMillis()+serverClockOffset>=me().optLong("nextAttackAt");
   String ammo=weapon.optBoolean("blackpowder")?me().optString("selectedAmmo","roundBall"):weapon.optString("ammo","");if(!ammo.isEmpty()&&!ammo.equals("null"))ready=ready&&me().optJSONObject("inventory").optInt(ammo)>0&&combatTarget()!=null;
   if(heldAttack.due(now,ready))attack();
  }
