  private void clampMap(float u){JSONObject size=state.optJSONObject("worldSize");float ww=size==null?62254:size.optInt("width",62254),hh=size==null?62254:size.optInt("height",62254);float width=getWidth(),height=Math.max(1,getHeight()-130*u),scale=Math.min((width-60*u)/ww,(height-10*u)/hh)*mapZoom;mapPanX=MapViewport.limit(mapPanX,ww*scale,width);mapPanY=MapViewport.limit(mapPanY,hh*scale,height);}
