  private boolean nearVillage(float x,float y){if(!state.optString("worldProfile").equals("day2-compact"))return false;JSONArray hubs=state.optJSONArray("settlements");if(hubs!=null)for(int i=0;i<hubs.length();i++){JSONObject hub=hubs.optJSONObject(i);if(Math.hypot(x-hub.optDouble("x"),y-hub.optDouble("y"))<560)return true;}return false;}
  private boolean townRoad(JSONObject road){JSONArray pts=road.optJSONArray("points");if(pts==null)return false;for(int i=0;i<pts.length();i++){JSONObject pt=pts.optJSONObject(i);if(nearVillage((float)pt.optDouble("x"),(float)pt.optDouble("y")))return true;}return false;}
