  private final Path wallFace=new Path();
  private void drawCastleWall(Canvas c,float x,float y,float x2,float y2){float h=65;wallFace.reset();wallFace.moveTo(x,y);wallFace.lineTo(x2,y2);wallFace.lineTo(x2-h,y2-h);wallFace.lineTo(x-h,y-h);wallFace.close();paint.setColor(0xff555d57);c.drawPath(wallFace,paint);paint.setStrokeWidth(12);paint.setColor(0xffa09e88);c.drawLine(x-h,y-h,x2-h,y2-h,paint);paint.setStrokeWidth(2);paint.setColor(0xff747b6e);for(int row=1;row<5;row++){float z=h*row/5;c.drawLine(x-z,y-z,x2-z,y2-z,paint);}int count=Math.max(1,(int)(Math.hypot(x2-x,y2-y)/38));for(int i=0;i<=count;i++){float xx=x+(x2-x)*i/count,yy=y+(y2-y)*i/count;paint.setStrokeWidth(13);paint.setColor(0xffb1ab93);c.drawLine(xx-h,yy-h,xx-h-13,yy-h-13,paint);}}
