  private float aimDX(JSONObject obj,boolean mine){if(gathering(obj))return (float)obj.optDouble("gatherDX",1);return mine&&SystemClock.elapsedRealtime()-localSwingAt<600?localAimDX:(float)obj.optDouble("attackDX",1);}
  private float aimDY(JSONObject obj,boolean mine){if(gathering(obj))return (float)obj.optDouble("gatherDY",0);return mine&&SystemClock.elapsedRealtime()-localSwingAt<600?localAimDY:(float)obj.optDouble("attackDY",0);}
  private boolean gathering(JSONObject obj){long age=System.currentTimeMillis()+serverClockOffset-obj.optLong("lastGather");return obj.optLong("lastGather")>obj.optLong("lastAttack")&&age>=0&&age<500;}
  private String animationWeapon(JSONObject obj,boolean mine){if(gathering(obj))return obj.optString("gatherTool");if(mine&&SystemClock.elapsedRealtime()-localSwingAt<600)return localSwingWeapon;if(attackPhase(obj)>=0&&obj.has("attackWeapon"))return obj.optString("attackWeapon");return mine?equippedWeapon():obj.optString("equippedWeapon");}
  private float attackPhase(JSONObject actor){if(gathering(actor))return (System.currentTimeMillis()+serverClockOffset-actor.optLong("lastGather"))/500f;if(actor==me()){long localAge=SystemClock.elapsedRealtime()-localSwingAt;if(localAge>=0&&localAge<600)return localAge/600f;}long age=System.currentTimeMillis()+serverClockOffset-actor.optLong("lastAttack");return age>=0&&age<500?age/500f:-1;}
  private void meter(Canvas c,String title,double value,float x,float y,int color,float u){double max=title.equals("HEALTH")?me().optDouble("maxHp",100):title.equals("STAMINA")?me().optDouble("maxStamina",100):100;float amount=(float)Math.max(0,Math.min(max,value));paint.setColor(0xdd15191a);c.drawRect(x*u,y*u,(x+146)*u,(y+32)*u,paint);paint.setColor(color);c.drawRect((x+3)*u,(y+22)*u,(x+3+140*amount/(float)max)*u,(y+29)*u,paint);paint.setColor(Color.WHITE);paint.setTextSize(12*u);c.drawText(title+" "+Math.round(amount),(x+5)*u,(y+16)*u,paint);}
